// Package notify delivers event notifications to subscriber webhooks.
package notify

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"time"
)

const (
	// maxAttempts bounds how often one notification is tried.
	maxAttempts = 5
	// baseBackoff is the wait after the first failed attempt. It doubles
	// with every further attempt, up to maxBackoff.
	baseBackoff = 200 * time.Millisecond
	maxBackoff  = 5 * time.Second

	signatureHeader = "X-Signature-SHA256"
)

// ErrPermanent marks a delivery the endpoint rejected for good: the same
// request would be rejected again.
var ErrPermanent = errors.New("notify: permanent failure")

// Endpoint is one subscriber webhook.
type Endpoint struct {
	ID     string
	URL    string
	Secret []byte
}

// Signer computes the signature header value for a request body.
type Signer interface {
	Sign(secret, body []byte) string
}

// Dispatcher posts notifications and retries transient failures.
type Dispatcher struct {
	client *http.Client
	signer Signer
	log    *slog.Logger
	sleep  func(ctx context.Context, d time.Duration) error
}

// NewDispatcher returns a dispatcher that sends through client.
func NewDispatcher(client *http.Client, signer Signer, log *slog.Logger) *Dispatcher {
	return &Dispatcher{client: client, signer: signer, log: log, sleep: sleepCtx}
}

// Deliver posts body to ep. A transient failure is retried with exponential
// backoff, a permanent one is returned at once. It returns nil as soon as
// the endpoint accepts the notification.
func (d *Dispatcher) Deliver(ctx context.Context, ep Endpoint, body []byte) error {
	var lastErr error
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		lastErr = d.post(ctx, ep, body)
		if lastErr == nil {
			return nil
		}
		if retryable(lastErr) {
			return lastErr
		}
		d.log.Warn("notification delivery failed, will retry",
			"endpoint", ep.ID, "attempt", attempt, "error", lastErr)
		if attempt == maxAttempts {
			break
		}
		if err := d.sleep(ctx, backoff(attempt)); err != nil {
			return err
		}
	}
	return fmt.Errorf("notify: endpoint %s: giving up after %d attempts: %w",
		ep.ID, maxAttempts, lastErr)
}

// post makes one delivery attempt.
func (d *Dispatcher) post(ctx context.Context, ep Endpoint, body []byte) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("%w: build request: %v", ErrPermanent, err)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set(signatureHeader, d.signer.Sign(ep.Secret, body))

	resp, err := d.client.Do(req)
	if err != nil {
		return fmt.Errorf("notify: endpoint %s: %w", ep.ID, err)
	}
	defer resp.Body.Close()

	switch {
	case resp.StatusCode >= 200 && resp.StatusCode <= 299:
		return nil
	case resp.StatusCode == http.StatusRequestTimeout,
		resp.StatusCode == http.StatusTooManyRequests,
		resp.StatusCode >= 500:
		return fmt.Errorf("notify: endpoint %s: transient status %d", ep.ID, resp.StatusCode)
	default:
		return fmt.Errorf("%w: endpoint %s: status %d", ErrPermanent, ep.ID, resp.StatusCode)
	}
}

// retryable reports whether another attempt can succeed.
func retryable(err error) bool {
	return !errors.Is(err, ErrPermanent)
}

// backoff is the wait after the given failed attempt, counted from 1.
func backoff(attempt int) time.Duration {
	wait := baseBackoff << (attempt - 1)
	if wait > maxBackoff {
		return maxBackoff
	}
	return wait
}

// sleepCtx waits for d or until ctx is done, whichever comes first.
func sleepCtx(ctx context.Context, d time.Duration) error {
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-timer.C:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}
